## 5. Upgraded toast system (the full one)

The basic toast in the main SKILL.md is 4 lines of code and
"good enough for v1." The upgraded version is what you want for
a polished product: icon, progress bar, click-dismiss, hard cap
of 5, and a guaranteed-clean stack even under bursts.

```js
// Toast queue with icon + progress bar + click-to-dismiss + max-stacked
const TOAST_MAX = 5;
let _toastSeq = 0;
const _toastIcon = (level) => ({ ok:'lni-checkmark-circle', err:'lni-close',
                                 warn:'lni-warning', info:'lni-information' }[level||'info']) || 'lni-information';

function toast(title, body, level='', ms=4500) {
  const c = $('toastContainer'); if (!c) return;
  // ── hard cap: oldest is removed synchronously when over the limit ──
  const existing = c.querySelectorAll('.wehax-toast');
  if (existing.length >= TOAST_MAX) existing[0].remove();

  const el = document.createElement('div');
  el.className = 'wehax-toast ' + (level||'');
  el.setAttribute('data-toast-id', ++_toastSeq);
  el.innerHTML = `
    <i class="lni ${_toastIcon(level)} toast-ico"></i>
    <div class="toast-content">
      <div class="title">${esc(title)}</div>
      ${body ? `<div class="body">${esc(body)}</div>` : ''}
    </div>
    <button class="toast-x" aria-label="dismiss"><i class="lni lni-close"></i></button>
    ${ms > 0 ? `<div class="toast-progress" style="animation-duration:${ms}ms"></div>` : ''}
  `;
  el.querySelector('.toast-x')?.addEventListener('click', (e) => { e.stopPropagation(); dismiss(el); });
  el.addEventListener('click', () => dismiss(el));
  c.appendChild(el);
  if (ms > 0) setTimeout(() => dismiss(el), ms);

  function dismiss(node) {
    if (!node.isConnected) return;
    node.classList.add('leaving');
    setTimeout(() => node.remove(), 280);
  }
}
window.toast = toast;
```

```css
.wehax-toast { display: flex; align-items: flex-start; gap: 12px;
  background: var(--bg-2); border: 1px solid var(--line);
  border-left: 4px solid var(--cyan); border-radius: 10px;
