# Theme system + responsive layout (4-breakpoint mobile-first)

The class of work: build a single-page dashboard that flips between
dark / light / system themes and adapts gracefully from 1920px desktop
to 360px phone, with no build step and no framework.

Two non-obvious traps account for 90% of the failures:
1. **CSS custom property cascade gotcha** — overriding on `body` doesn't
   propagate to `getComputedStyle(documentElement)`, which is what
   canvas-rendered visualizations need.
2. **Hardcoded canvas colors** — if you style your theme via CSS vars
   but the canvas uses hardcoded `'#e6edf3'`, the canvas stays light
   text on a dark background when the theme flips to light. Invisible
   labels, invisible particles.

## Theme: 3-way cycle on a single button

The minimal viable theme system: one button, three states, persisted to
localStorage, flows through CSS custom properties so all surfaces swap
together.

```html
<button id="themeBtn"><i class="lni lni-night"></i></button>
```

```js
const setThemeIcon = () => {
  const ico = $('themeBtn')?.querySelector('i');
  if (!ico) return;
  // system-theme is checked FIRST so the gear icon wins over the
  // .light class that's also present in system mode
  if (document.documentElement.classList.contains('system-theme')) {
    ico.className = 'lni lni-cog';
  } else if (document.documentElement.classList.contains('light')) {
    ico.className = 'lni lni-sun';
  } else {
    ico.className = 'lni lni-night';
  }
};

const applyTheme = (mode) => {
  document.documentElement.classList.remove('light', 'system-theme');
  if (mode === 'light') {
    document.documentElement.classList.add('light');
  } else if (mode === 'system') {
    document.documentElement.classList.add('system-theme');
    const prefersDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches;
    if (prefersDark) document.documentElement.classList.remove('light');
    else document.documentElement.classList.add('light');
    // re-apply when the OS preference changes (only while in system mode)
    window.matchMedia?.('(prefers-color-scheme: dark)')
      .addEventListener?.('change', () => {
        if (document.documentElement.classList.contains('system-theme')) applyTheme('system');
      });
  }
  setThemeIcon();
};

on('themeBtn', () => {
  let next = 'dark';
  if (document.documentElement.classList.contains('light')) next = 'system';
  else if (document.documentElement.classList.contains('system-theme')) next = 'dark';
  else next = 'light';
  applyTheme(next);
  try { localStorage.setItem('wehax.theme', next); } catch {}
});

// boot: restore from localStorage
async function boot() {
  try {
    const t = localStorage.getItem('wehax.theme') || 'dark';
    if (t === 'light') document.documentElement.classList.add('light');
    else if (t === 'system') {
      document.documentElement.classList.add('system-theme');
      const prefersDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches;
      if (!prefersDark) document.documentElement.classList.add('light');
    }
    const ico = $('themeBtn')?.querySelector('i');
    if (ico) {
      if (t === 'light') ico.className = 'lni lni-sun';
      else if (t === 'system') ico.className = 'lni lni-cog';
    }
  } catch {}
  // ...
}
```

