  .sidebar-nav-wrapper .logo-sub { display: none; }
  .sidebar-nav-wrapper.expanded .logo-text,
  .sidebar-nav-wrapper.expanded .logo-sub { display: block; }
  .sidebar-nav .nav-item > a { justify-content: center; }
  .sidebar-nav-wrapper.expanded .nav-item > a { justify-content: flex-start; }
  .sidebar-nav .nav-item > a .text,
